// Datos del juego

const DICE = {
    classic: { row: 0, vals: [1, 2, 3, 4, 5, 6], cost: 0 },
    num: { row: 1, vals: [2, 4, 6, 8, 10, 12], cost: 400 },
    sym: { row: 2, vals: [4, 0, 6, 12, "?", 30], cost: 4000 },
    royal: { row: 4, vals: [20, 30, 40, 60, 80, 150], cost: 40000 }
};

const UPGRADES = {
    mult: { base: 15, growth: 1.6, max: 999 },
    luck: { base: 40, growth: 1.9, max: 10 },
    auto: { base: 100, growth: 2.2, max: 12 }
};

const SKINS = {
    white: { img: "white", filter: "", cost: 0 },
    pink: { img: "pink", filter: "", cost: 250 },
    sky: { img: "pink", filter: "hue-rotate(200deg)", cost: 1500 },
    mint: { img: "pink", filter: "hue-rotate(110deg)", cost: 6000 },
    gold: { img: "pink", filter: "hue-rotate(320deg) saturate(1.6)", cost: 25000 }
};

const STAGES = [0, 500, 5e3, 5e4, 5e5, 5e6];

// ===== Inventario =====

const STORAGE_KEY = "diceandroll_v1";

let state = {
    money: 0,
    total: 0,
    rolls: 0,
    up: { mult: 0, luck: 0, auto: 0 },
    dice: { classic: 1 },
    skin: "white",
    skins: { white: 1 },
    lang: navigator.language && navigator.language.startsWith("en") ? "en" : "es",
    snd: 1
};

try {
    const saved = localStorage.getItem(STORAGE_KEY);
    if (saved) {
        state = Object.assign(state, JSON.parse(saved));
    }
} catch (error) {
    // Ignore unavailable or invalid stored progress.
}

let paused = false;
let rolling = false;
let tab = 0;
let accumulatedAutoRoll = 0;
let audioContext = null;
let faces = {};

// ===== Helpers de DOM =====

const getElement = (id) => document.getElementById(id);
const translate = () => T[state.lang];

function formatNumber(value) {
    let number = Math.floor(value);
    if (number < 1e4) {
        return String(number);
    }

    const units = ["", "K", "M", "B", "T"];
    let unitIndex = 0;

    while (number >= 1e3 && unitIndex < 4) {
        number /= 1e3;
        unitIndex += 1;
    }

    return (number >= 100 ? number.toFixed(0) : number.toFixed(1))
        .replace(/\.0$/, "") + units[unitIndex];
}

function saveProgress() {
    try {
        localStorage.setItem(STORAGE_KEY, JSON.stringify(state));
    } catch (error) {
        // Ignorar el inventario no disponible.
    }
}

// ===== Audio y sprites =====

function playBeep(frequency, duration) {
    if (!state.snd) {
        return;
    }

    try {
        audioContext = audioContext || new (window.AudioContext || window.webkitAudioContext)();
        const oscillator = audioContext.createOscillator();
        const gain = audioContext.createGain();

        oscillator.frequency.value = frequency;
        oscillator.type = "square";
        gain.gain.value = 0.025;
        oscillator.connect(gain);
        gain.connect(audioContext.destination);
        oscillator.start();

        setTimeout(() => {
            gain.gain.exponentialRampToValueAtTime(0.001, audioContext.currentTime + duration);
            oscillator.stop(audioContext.currentTime + duration);
        }, 20);
    } catch (error) {
        // Ignorar el audio web no disponible.
    }
}

function setSprite(element, sheet, filter, size, row, column) {
    const skin = SKINS[sheet] ? SKINS[sheet] : SKINS[state.skin];
    element.style.backgroundImage = `url(${IMG[skin.img]})`;
    element.style.backgroundSize = `${size * 6}px ${size * 6}px`;
    element.style.backgroundPosition = `${-column * size}px ${-row * size}px`;
    element.style.filter = filter !== undefined ? filter : skin.filter;
}

function getOwnedDice() {
    return Object.keys(DICE).filter((key) => state.dice[key]);
}

// ===== Dado =====

function buildDice() {
    const box = getElement("dice");
    box.innerHTML = "";

    getOwnedDice().forEach((key) => {
        const die = document.createElement("div");
        die.className = "die";
        die.dataset.key = key;
        box.appendChild(die);

        setSprite(die, state.skin, undefined, 96, DICE[key].row, faces[key] ?? 0);
    });
}

function showFaces() {
    document.querySelectorAll(".die").forEach((die) => {
        const key = die.dataset.key;
        setSprite(die, state.skin, undefined, 96, DICE[key].row, faces[key] ?? 0);
    });
}

function randomFace() {
    return Math.floor(Math.random() * 6);
}

function rollDice() {
    if (rolling || paused) {
        return;
    }

    rolling = true;
    playBeep(220, 0.08);

    const diceElements = [...document.querySelectorAll(".die")];
    diceElements.forEach((die) => die.classList.add("rolling"));

    let frame = 0;
    const animation = setInterval(() => {
        diceElements.forEach((die) => {
            setSprite(die, state.skin, undefined, 96, 5, frame % 6);
        });
        frame += 1;
    }, 80);

    getElement("roll").disabled = true;
    getElement("roll").textContent = translate().rolling;

    setTimeout(() => {
        clearInterval(animation);

        const luck = state.up.luck * 0.08;
        const multiplier = 1 + 0.25 * state.up.mult;
        let reward = 0;

        diceElements.forEach((die) => {
            const key = die.dataset.key;
            let face = randomFace();

            if (Math.random() < luck) {
                face = Math.max(face, randomFace());
            }

            faces[key] = face;

            let value = DICE[key].vals[face];
            if (value === "?") {
                value = 1 + Math.floor(Math.random() * 40);
            }

            const gain = Math.round(value * multiplier);
            reward += gain;

            die.classList.remove("rolling");
            setSprite(die, state.skin, undefined, 96, DICE[key].row, face);

            const popup = document.createElement("div");
            popup.className = "pop";
            popup.textContent = `+${formatNumber(gain)}`;
            die.appendChild(popup);
            setTimeout(() => popup.remove(), 1000);
        });

        state.money += reward;
        state.total += reward;
        state.rolls += 1;
        rolling = false;

        playBeep(reward > 0 ? 660 : 150, 0.12);
        getElement("roll").disabled = false;
        getElement("roll").textContent = translate().roll;

        refreshUI();
        saveProgress();
    }, 560);
}

// ===== Tienda =====

function upgradeCost(key) {
    return Math.ceil(UPGRADES[key].base * Math.pow(UPGRADES[key].growth, state.up[key]));
}

function getShopItems() {
    const items = [];

    Object.keys(UPGRADES).forEach((key) => {
        items.push({
            key: `u${key}`,
            icon: ["white", 0, key === "auto" ? 5 : 2, key === "mult" ? 5 : key === "luck" ? 4 : 1],
            name: translate()[key][0],
            description: translate()[key][1] + (key === "auto" ? ` (${state.up.auto * 0.25}/s)` : ""),
            level: state.up[key],
            price: upgradeCost(key),
            max: state.up[key] >= UPGRADES[key].max,
            buy: () => {
                state.up[key] += 1;
            }
        });
    });

    Object.keys(DICE).forEach((key) => {
        items.push({
            key: `d${key}`,
            icon: ["white", 0, DICE[key].row, 0],
            name: translate().d[key][0],
            description: translate().d[key][1],
            price: DICE[key].cost,
            owned: Boolean(state.dice[key]),
            buy: () => {
                state.dice[key] = 1;
                buildDice();
            }
        });
    });

    Object.keys(SKINS).forEach((key) => {
        items.push({
            key: `s${key}`,
            icon: [key, 0, 0, 0],
            name: translate().s[key],
            description: "",
            price: SKINS[key].cost,
            owned: Boolean(state.skins[key]),
            equipped: state.skin === key,
            buy: () => {
                state.skins[key] = 1;
                state.skin = key;
                showFaces();
            },
            equip: () => {
                state.skin = key;
                showFaces();
            }
        });
    });

    return items;
}

function renderShop() {
    const list = getElement("list");
    list.innerHTML = "";

    const allItems = getShopItems();
    const visibleItems = tab === 0
        ? allItems.filter((item) => item.key[0] === "u")
        : tab === 1
            ? allItems.filter((item) => item.key[0] === "d")
            : allItems.filter((item) => item.key[0] === "s");

    visibleItems.forEach((item) => {
        const row = document.createElement("div");
        row.className = "item";

        const icon = document.createElement("div");
        icon.className = "ic";
        const skin = SKINS[item.icon[0]];
        setSprite(icon, item.icon[0], skin ? skin.filter : "", 48, item.icon[2], item.icon[3]);

        const text = document.createElement("div");
        text.className = "tx";
        text.innerHTML = "<b></b><small></small>";
        text.firstChild.textContent = item.name + (item.level !== undefined ? ` \u00b7 ${translate().lvl} ${item.level}` : "");
        text.lastChild.textContent = item.description;

        const button = document.createElement("button");
        button.className = "btn";

        if (item.max) {
            button.textContent = translate().max;
            button.disabled = true;
        } else if (item.owned !== undefined) {
            if (item.owned) {
                if (item.key[0] === "s") {
                    button.textContent = item.equipped ? translate().equipped : translate().equip;
                    if (item.equipped) {
                        button.classList.add("eq");
                        button.disabled = true;
                    } else {
                        button.onclick = () => {
                            item.equip();
                            renderShop();
                            saveProgress();
                        };
                    }
                } else {
                    button.textContent = translate().owned;
                    button.disabled = true;
                    button.classList.add("eq");
                }
            } else {
                button.textContent = `${formatNumber(item.price)} $`;
                button.disabled = state.money < item.price;
                button.onclick = () => purchaseItem(item);
            }
        } else {
            button.textContent = `${formatNumber(item.price)} $`;
            button.disabled = state.money < item.price;
            button.onclick = () => purchaseItem(item);
        }

        row.append(icon, text, button);
        list.appendChild(row);
    });
}

function purchaseItem(item) {
    if (state.money < item.price) {
        return;
    }

    state.money -= item.price;
    item.buy();
    playBeep(880, 0.1);
    refreshUI();
    renderShop();
    saveProgress();
}

// ===== Interfaz de usuario =====

function refreshUI() {
    getElement("money").textContent = formatNumber(state.money);

    let stageIndex = 0;
    STAGES.forEach((threshold, index) => {
        if (state.total >= threshold) {
            stageIndex = index;
        }
    });

    const nextStage = STAGES[stageIndex + 1];
    getElement("stage").textContent = `${translate().stages[stageIndex]} \u00b7 ${nextStage
        ? `${translate().next}: ${formatNumber(state.total)} / ${formatNumber(nextStage)}`
        : translate().top}`;

    const progress = nextStage
        ? Math.min(100, (state.total - STAGES[stageIndex]) / (nextStage - STAGES[stageIndex]) * 100)
        : 100;
    getElement("prog").style.width = `${progress}%`;

    refreshShopButtons();
}

function refreshShopButtons() {
    const allItems = getShopItems();
    const visibleItems = tab === 0
        ? allItems.filter((item) => item.key[0] === "u")
        : tab === 1
            ? allItems.filter((item) => item.key[0] === "d")
            : allItems.filter((item) => item.key[0] === "s");

    const rows = getElement("list").children;
    visibleItems.forEach((item, index) => {
        const button = rows[index] && rows[index].querySelector("button");
        if (!button) {
            return;
        }

        if (item.max || (item.owned && (item.key[0] !== "s" || item.equipped))) {
            return;
        }

        if (item.owned) {
            return;
        }

        button.disabled = state.money < item.price;
    });
}

function renderTexts() {
    document.documentElement.lang = state.lang;
    const text = translate();

    getElement("ml").textContent = text.money;
    getElement("roll").textContent = rolling ? text.rolling : text.roll;
    getElement("hint").textContent = text.hint;
    getElement("pbtn").textContent = text.pause;
    getElement("ptitle").textContent = text.paused;
    getElement("snd").textContent = `${text.sound}: ${state.snd ? text.on : text.off}`;
    getElement("reset").textContent = text.reset;
    getElement("plang").textContent = "ES / EN";
    getElement("credit").textContent = text.credit;
    getElement("foot").textContent = text.credit;

    const tabs = getElement("tabs");
    tabs.innerHTML = "";

    text.tabs.forEach((label, index) => {
        const button = document.createElement("button");
        button.className = "btn";
        button.setAttribute("role", "tab");
        button.setAttribute("aria-selected", index === tab);
        button.textContent = label;
        button.onclick = () => {
            tab = index;
            renderTexts();
        };
        tabs.appendChild(button);
    });

    renderShop();
    refreshUI();
}

function setPaused(value) {
    paused = value;
    getElement("pause").classList.toggle("on", value);
}

function toggleLanguage() {
    state.lang = state.lang === "es" ? "en" : "es";
    renderTexts();
    saveProgress();
}

// ===== Eventos =====

getElement("lang").onclick = toggleLanguage;
getElement("plang").onclick = toggleLanguage;
getElement("pbtn").onclick = () => setPaused(true);
getElement("resume").onclick = () => setPaused(false);

getElement("snd").onclick = () => {
    state.snd = state.snd ? 0 : 1;
    renderTexts();
    saveProgress();
};

getElement("reset").onclick = () => {
    if (confirm(translate().ask)) {
        try {
            localStorage.removeItem(STORAGE_KEY);
        } catch (error) {
            // Ignore unavailable storage.
        }
        location.reload();
    }
};

getElement("roll").onclick = rollDice;
getElement("table").addEventListener("click", (event) => {
    if (event.target.id === "table" || event.target.classList.contains("die") || event.target.id === "dice") {
        rollDice();
    }
});

document.addEventListener("keydown", (event) => {
    if (event.key === "Escape") {
        setPaused(!paused);
    }
});

// ===== Bucle de giro automático =====

let lastAutoRollTime = performance.now();

setInterval(() => {
    const now = performance.now();
    const elapsedSeconds = (now - lastAutoRollTime) / 1000;
    lastAutoRollTime = now;

    if (paused || !state.up.auto) {
        return;
    }

    accumulatedAutoRoll += elapsedSeconds * state.up.auto * 0.25;

    if (accumulatedAutoRoll >= 1 && !rolling) {
        accumulatedAutoRoll = 0;
        rollDice();
    }
}, 100);

setInterval(saveProgress, 5000);

// ===== Inicialización =====

buildDice();
renderTexts();